export type ParsedBuyTokenCardInstruction<
  TProgram extends string = typeof SAFECARD_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    buyer: TAccountMetas[0];
    merchant: TAccountMetas[1];
    plan: TAccountMetas[2];
    mint: TAccountMetas[3];
    stats: TAccountMetas[4];
    buyerTokenAccount: TAccountMetas[5];
    card: TAccountMetas[6];
    /** 托管账户：authority 是卡片 PDA，只有程序能动 */
    vault: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    associatedTokenProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
  };
  data: BuyTokenCardInstructionData;
};

export function parseBuyTokenCardInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBuyTokenCardInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      buyer: getNextAccount(),
      merchant: getNextAccount(),
      plan: getNextAccount(),
      mint: getNextAccount(),
      stats: getNextAccount(),
      buyerTokenAccount: getNextAccount(),
      card: getNextAccount(),
      vault: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getBuyTokenCardInstructionDataDecoder().decode(instruction.data),
  };
}
